<script setup lang="ts">
import { onMounted,ref,watch } from 'vue'
import { getRegisteredApps,listAppPeople,type RegisteredApp } from '@/services/iamWork'
import { listPeople } from '@/services/iamPeople'
import { iamMessage } from '@/services/iamAccess'
import type { EmployeeSummary } from '@/types/iam'
import EmployeeDrawer from '@/components/iam/EmployeeDrawer.vue'
const viewGroup=ref('daily'),groupsAvailable=ref(false)
const apps=ref<RegisteredApp[]>([]),rows=ref<EmployeeSummary[]>([]),selectedApp=ref('attendance'),search=ref(''),page=ref(1),total=ref(0),loading=ref(true),error=ref(''),employeeId=ref(''),drawerOpen=ref(false)
let generation=0,timer:ReturnType<typeof setTimeout>|undefined
const columns=[{title:'姓名 / 工号',key:'name',width:'28%'},{title:'部门',dataIndex:'department_name',width:'28%'},{title:'账号',key:'account',width:'24%'},{title:'操作',key:'action',width:'20%'}]
async function load(){if(!selectedApp.value)return;const run=++generation;loading.value=true;error.value='';try{const data=await listAppPeople(selectedApp.value,{page:page.value,page_size:20,search:search.value,view_group:viewGroup.value});if(run===generation){rows.value=data.items;total.value=data.total;groupsAvailable.value=data.groups_available===true}}catch(e){if(run===generation){rows.value=[];total.value=0;error.value=iamMessage(e)}}finally{if(run===generation)loading.value=false}}
onMounted(async()=>{try{apps.value=(await getRegisteredApps()).apps.filter(app=>app.id!=='iam'&&(!app.synthetic||app.integrated));selectedApp.value=apps.value.find(app=>app.integrated)?.id||''}catch(e){error.value=iamMessage(e)}await load()});watch(search,()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,300)});watch(viewGroup,()=>{page.value=1;void load()});watch(selectedApp,()=>{page.value=1;void load()})
</script>
<template><section><div class="iam-heading"><div><h1>应用权限</h1><p>先选择应用，再查看同一员工的工作、对象与设置来源。</p></div></div><section class="application-overview"><button v-for="app in apps" :key="app.id" :aria-pressed="selectedApp===app.id" class="application-card" @click="selectedApp=app.id"><strong>{{app.title}}</strong><span>{{app.synthetic?'隔离合成规则验证，非库存业务接入':app.integrated?'已接入本管理功能':'尚未接入此管理功能'}}</span><small v-if="!app.integrated">原有业务沿用现有授权，暂不能在此调整。</small></button></section><section class="iam-panel"><h2>员工应用权限</h2><div class="iam-toolbar"><a-select v-if="groupsAvailable" v-model:value="viewGroup" aria-label="员工分组" style="min-width:160px"><a-select-option value="daily">日常员工</a-select-option><a-select-option value="technical">技术验证夹具</a-select-option><a-select-option value="all">全部员工</a-select-option></a-select><a-input v-model:value="search" class="iam-search" placeholder="搜索员工姓名或工号" aria-label="搜索应用员工" allow-clear/></div><a-alert v-if="error" :message="error" type="warning"/><a-table :columns="columns" :data-source="rows" row-key="id" table-layout="fixed" :scroll="{x:650}" :loading="loading" :pagination="{current:page,pageSize:20,total,showSizeChanger:false,onChange:(value:number)=>{page=value;load()}}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><button class="iam-name" :aria-label="`查看${record.name}的应用权限，工号${record.employee_number}`" @click="employeeId=record.id;drawerOpen=true"><strong>{{record.name}}</strong></button><span class="iam-code">{{record.employee_number}}</span></template><template v-else-if="column.key==='account'">{{record.account_status==='active'?'已开通':record.account_status==='disabled'?'已停用':'尚未开户，先看所属部门权限'}}</template><template v-else-if="column.key==='action'"><a-button type="link" @click="employeeId=record.id;drawerOpen=true">设置权限</a-button></template></template></a-table></section><EmployeeDrawer :open="drawerOpen" :employee-id="employeeId" initial-tab="apps" :initial-app="apps.find(app=>app.id===selectedApp)?.integrated?selectedApp:null" @close="drawerOpen=false" @changed="load"/></section></template>
<style scoped>.application-overview{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-bottom:24px}.application-card{font:inherit;text-align:left;border:1px solid var(--hbos-border-subtle,#dbe4df);border-radius:16px;background:#fff;padding:20px;display:grid;gap:10px;cursor:pointer;min-width:0}.application-card[aria-pressed=true]{border-color:#548666;box-shadow:0 0 0 2px #54866620}.application-card strong{font-size:18px;overflow-wrap:anywhere}.application-card span,.application-card small{font-size:14px;color:var(--hbos-text-secondary)}</style>
